/**
 * Entries the AI has already said are not words, so the same text is not
 * sent again. Learners retried an entry it did not know up to six times
 * (24 Oct 2026), and each retry cost an AI call that could only get the same
 * answer. A changed spelling is a new question and goes to the AI as usual.
 *
 * Held in memory for this tab only: it is a guard against asking twice in a
 * row, not a record. A reload, or a new prompt on the server, asks afresh.
 */
import { normalizeHeadword, type LanguageCode } from '@lexpad/core';

const refused = new Set<string>();

function key(language: LanguageCode, entry: string): string {
  return `${language}\u0000${normalizeHeadword(entry)}`;
}

/** The AI said these entries are not words in `language`. */
export function rememberUnknown(language: LanguageCode, entries: readonly string[]): void {
  for (const entry of entries) {
    if (entry.trim() !== '') refused.add(key(language, entry));
  }
}

/** Whether the AI already said this exact entry (once normalised) is not a word in `language`. */
export function knownUnknown(language: LanguageCode, entry: string): boolean {
  return entry.trim() !== '' && refused.has(key(language, entry));
}

/** Forgets every answer, so each test starts from nothing. */
export function forgetUnknown(): void {
  refused.clear();
}
